def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    value = high - low
    return {
        "value": value,
        "trace": {
            "high_share_price": high,
            "low_share_price": low,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
